  "repair_strategy": "Update the tabbable nodes in checkFocusIn before attempting to restore focus, and perform the focus restoration synchronously. The restoration logic will prefer the most recently focused node if it is still contained in a trap container; otherwise it will directly use the first tabbable node from the first tabbable group (which reflects the updated DOM) as a fallback, avoiding any indirection through getInitialFocusNode that might rely on stale state.",
  "edits": [
    {
      "path": "index.js",
      "sha256": "5a4e96cb8f9bb206fe799f923488aab6f2f6d9fc4f1f9fc6023f04aa63ad9a0d",
      "before": "  // In case focus escapes the trap for some strange reason, pull it back in.
  const checkFocusIn = function (e) {
    const target = getActualTarget(e);
    const targetContained = findContainerIndex(target, e) >= 0;

    // In Firefox when you Tab out of an iframe the Document is briefly focused.
    if (targetContained || target instanceof Document) {
      if (targetContained) {
        state.mostRecentlyFocusedNode = target;
      }
    } else {
      // escaped! pull it back in to where it just left
      e.stopImmediatePropagation();
      tryFocus(state.mostRecentlyFocusedNode || getInitialFocusNode());
    }
  };",
      "after": "  // In case focus escapes the trap for some strange reason, pull it back in.
  const checkFocusIn = function (e) {
    const target = getActualTarget(e);
    const targetContained = findContainerIndex(target, e) >= 0;

    // In Firefox when you Tab out of an iframe the Document is briefly focused.
    if (targetContained || target instanceof Document) {
      if (targetContained) {
        state.mostRecentlyFocusedNode = target;
      }
    } else {
      // escaped! pull it back in to where it just left
      e.stopImmediatePropagation();
      // Update tabbable nodes in case the DOM changed (e.g., focused node removed)
      updateTabbableNodes();
      // Determine the node to focus: prefer the most recently focused node if still in a container,
      // otherwise fall back to the first tabbable node in the first tabbable group.
      let nodeToFocus = null;
      if (state.mostRecentlyFocusedNode && state.containers.some(container => container.contains(state.mostRecentlyFocusedNode))) {
        nodeToFocus = state.mostRecentlyFocusedNode;
      } else if (state.tabbableGroups.length > 0 && state.tabbableGroups[0].firstTabbableNode) {
        nodeToFocus = state.tabbableGroups[0].firstTabbableNode;
      } else {
        nodeToFocus = getInitialFocusNode();
      }
      tryFocus(nodeToFocus);
    }
  };"
    }
  ],
  "expected_accessibility_effect": "After activating the trap and removing the focused node (via the 'Show all 4 results' button), keyboard focus will remain trapped within the dialog, moving to the close button (the first tabbable node) when the focused node is removed. This ensures that subsequent tab navigation remains within the dialog and the focus-within assertion passes.",
  "functional_risks": [
    "Calling updateTabbableNodes on every focus escape adds a small performance cost, but focus escapes are rare.",
    "If the trap is deactivated before the focus restoration runs, tryFocus will early-return because state.active is false.",
    "Synchronous focus() during a focusin event may be ignored by some browsers, but stopping immediate propagation increases the chance of success."
